css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; }
.loader .pot { position: absolute; left: 2%; bottom: 6%; width: 26%; height: 34%; border-radius: 6px 6px 40% 40%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.loader .jar { position: absolute; right: 2%; bottom: 6%; width: 22%; height: 30%; border-radius: 4px 4px 20% 20%; background: color-mix(in srgb, var(--accent-2) 25%, transparent); box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent-2) 60%, transparent); overflow: hidden; }
.loader .jar::after { content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 20%; background: var(--accent-2); animation: still-collect calc(var(--loader-speed) * 4) ease-in-out infinite; }
.loader span { position: absolute; top: 12%; width: 15%; height: 44%; border-radius: 50%; box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 55%, transparent); animation: still-flow calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader span:nth-of-type(1) { left: 20%; }
.loader span:nth-of-type(2) { left: 33%; animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-of-type(3) { left: 46%; animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-of-type(4) { left: 59%; animation-delay: calc(var(--loader-speed) * .54); }
.loader span:nth-of-type(5) { left: 72%; animation-delay: calc(var(--loader-speed) * .72); }
@keyframes still-flow { 0%, 100% { box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent); transform: scale(1); } 40% { box-shadow: inset 0 0 0 3px var(--accent-2); transform: scale(1.07); } }
@keyframes still-collect { 0% { height: 12%; } 80%, 100% { height: 78%; } }
